"use client";

import type { SVGProps } from "react";
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Margin Checkbox: an empty box is a small paper tab with a hairline ring.
 * Checked or mixed, it takes the primary Button's oxblood face with a white
 * tick or dash, so a ticked box and the button read as one material.
 */
function Checkbox({
  className,
  indeterminate,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer inline-flex size-4.5 shrink-0 items-center justify-center rounded-sm border border-transparent",
        "bg-card shadow-(--control-edge)",
        "transition duration-fast ease-(--ease-out) hover:shadow-(--control-edge-hover)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        controlChecked,
        "data-[indeterminate]:bg-(image:--ox-face) data-[indeterminate]:text-primary-foreground data-[indeterminate]:shadow-(--ox-edge)",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        keepMounted
        data-slot="checkbox-indicator"
        className="grid size-full place-items-center text-current transition-opacity duration-fast data-[unchecked]:opacity-0"
      >
        {indeterminate ? (
          <span className="h-0.5 w-2 rounded-full bg-current" />
        ) : (
          <CheckIcon className="size-3.5 [&_path]:stroke-3" aria-hidden />
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };

// "solar:unread-linear" from Solar,
// the icon library this system pairs with, drawn inline so the installed
// component loads no icon at runtime. [BD-1029]
function CheckIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M7 12.9L10.1429 16.5L18 7.5"/>
    </svg>
  );
}
